KG_CODE("f:src/autoskill/recorder.py","\"\"\"The human-action Recorder (db8 = db6 Item 5, owner order 2026-11-01).\n\nA small Record button on the dashboard records everything the owner does - clicks with the\nelement under them, keyboard typing, the time of every action, applications launched, every\ncommand typed into cmd or PowerShell - and writes it as the SAME kgrow.flow run document an\nagent run produces, so Export, Save, Import and Play work unchanged and the saved file replays\nonline or offline, without an agent (R53: everything the owner listed, nothing filtered).\n\nRecording is READ-ONLY observation of the owner's own input (R08 is about synthesizing input;\nnothing is synthesized here - the low-level hooks only watch and always pass events on). Replay\nis the product acting through the daemon's dispatch, like every step it already runs. Input the\ntool itself injected (a live run's replay, the overlay) is not the owner's and is skipped: the\nrun's own record already holds those steps.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nimport queue\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime\nfrom typing import Any\n\nfrom .protocol import ErrorCode, ProtocolError\n\n# The processes whose windows are consoles: a command typed there is one desktop.type turn.\nTERMINAL_PROCESSES = {\"cmd.exe\", \"powershell.exe\", \"pwsh.exe\", \"conhost.exe\",\n                      \"openconsole.exe\", \"windowsterminal.exe\", \"wt.exe\", \"console.exe\"}\n\n# Virtual-key codes of the modifiers (a combination is recorded as one desktop.key turn).\nMODIFIER_KEYS = {0x10: \"shift\", 0x11: \"ctrl\", 0x12: \"alt\", 0x5B: \"win\", 0x5C: \"win\",\n                 0xA0: \"shift\", 0xA1: \"shift\", 0xA2: \"ctrl\", 0xA3: \"ctrl\",\n                 0xA4: \"alt\", 0xA5: \"alt\"}\nMODIFIER_ORDER = {\"ctrl\": 0, \"alt\": 1, \"shift\": 2, \"win\": 3}\n\n# Special keys named for desktop.key (printable keys and Enter go into the typed text).\nKEY_NAMES = {0x08: \"backspace\", 0x09: \"tab\", 0x0D: \"enter\", 0x1B: \"escape\", 0x20: \"space\",\n             0x21: \"pageup\", 0x22: \"pagedown\", 0x23: \"end\", 0x24: \"home\",\n             0x25: \"left\", 0x26: \"up\", 0x27: \"right\", 0x28: \"down\",\n             0x2D: \"insert\", 0x2E: \"delete\", 0x5B: \"win\", 0x5C: \"win\",\n             **{0x70 + i: f\"f{i + 1}\" for i in range(24)}}\n\n# The tool's own windows are never a recording target (dashboard/windows.py's rule).\nOWN_WINDOW_TITLES = (\"Kgrow.io Studio\",)\nOWN_TITLE_SUFFIX = \"Kgrow.io\"\n\nCLIENT = {\"name\": \"record\", \"agent\": \"owner\"}\n\n# db8 addendum 8 (the owner's idea): a light green transparent click-through layer covering\n# the screen while recording is active. Uses the same extended styles as the project's\n# desktop/overlay.py (WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOPMOST | WS_EX_NOACTIVATE |\n# WS_EX_TOOLWINDOW) so it never intercepts input, never takes focus, and is excluded from\n# screenshots (WDA_EXCLUDEFROMCAPTURE). The CAPTURE itself stays in the low-level hooks —\n# Microsoft's input model makes it impossible for a window to both receive input and pass it\n# through; the green layer is the owner's visual signal that the device is being listened to.\nGREEN = 0x0090E890                     # light green (BGR: RGB 144, 232, 144)\nGREEN_ALPHA = 50                        # ~20% opacity: clearly visible, never a hindrance\n\n\nclass RecordingOverlay:\n    \"\"\"The owner's green recording indicator: a full-virtual-screen, click-through,\n    topmost, no-activate, capture-excluded transparent window tinted light green.\"\"\"\n\n    def __init__(self) -> None:\n        self._hwnd = 0\n        self._class_atom = 0\n\n    def show(self) -> bool:\n        \"\"\"Create and show the green layer; False when not on Windows or it fails (the\n        recording works perfectly without the visual — this is best-effort).\"\"\"\n        import ctypes\n        from ctypes import wintypes as wt\n        if os.name != \"nt\":\n            return False\n        try:\n            user32 = ctypes.windll.user32\n            kernel32 = ctypes.windll.kernel32\n            gdi32 = ctypes.windll.gdi32          # CreateSolidBrush is a GDI function\n            instance = kernel32.GetModuleHandleW(None)\n\n            class WNDCLASSEXW(ctypes.Structure):\n                _fields_ = [(\"cbSize\", ctypes.c_uint32), (\"style\", ctypes.c_uint32),\n                            (\"lpfnWndProc\", ctypes.c_void_p), (\"cbClsExtra\", ctypes.c_int32),\n                            (\"cbWndExtra\", ctypes.c_int32), (\"hInstance\", wt.HINSTANCE),\n                            (\"hIcon\", wt.HICON), (\"hCursor\", ctypes.c_void_p),\n                            (\"hbrBackground\", wt.HBRUSH), (\"lpszMenuName\", wt.LPCWSTR),\n                            (\"lpszClassName\", wt.LPCWSTR), (\"hIconSm\", wt.HICON)]\n\n            brush = gdi32.CreateSolidBrush(GREEN)\n            wc = WNDCLASSEXW()\n            wc.cbSize = ctypes.sizeof(WNDCLASSEXW)\n            wc.hInstance = instance\n            wc.hbrBackground = brush\n            wc.lpszClassName = \"AutoskillRecordTint\"\n            # db8 addendum 8 crash fix: lpfnWndProc must be DefWindowProcW — with it\n            # unset (0), Windows calls address 0 on the first message and the process dies\n            user32.DefWindowProcW.restype = ctypes.c_ssize_t\n            wc.lpfnWndProc = ctypes.cast(user32.DefWindowProcW, ctypes.c_void_p)\n            self._class_atom = user32.RegisterClassExW(ctypes.byref(wc))\n            if not self._class_atom:\n                err = kernel32.GetLastError()\n                if err != 1410:             # already registered (a prior recording)\n                    return False\n\n            # the virtual screen (all monitors)\n            left = user32.GetSystemMetrics(76)          # SM_XVIRTUALSCREEN\n            top = user32.GetSystemMetrics(77)           # SM_YVIRTUALSCREEN\n            width = user32.GetSystemMetrics(78)         # SM_CXVIRTUALSCREEN\n            height = user32.GetSystemMetrics(79)        # SM_CYVIRTUALSCREEN\n            ex = (0x00080000 | 0x00000020 | 0x00000008 | 0x00000080 | 0x08000000)\n            self._hwnd = user32.CreateWindowExW(\n                ex, \"AutoskillRecordTint\", \"recording\", 0x80000000,  # WS_POPUP\n                left, top, width, height, None, None, instance, None)\n            if not self._hwnd:\n                return False\n            # excluded from screenshots (the project's overlay convention)\n            try:\n                user32.SetWindowDisplayAffinity(self._hwnd, 0x11)    # WDA_EXCLUDEFROMCAPTURE\n            except Exception:                                   # noqa: BLE001\n                pass\n            user32.SetLayeredWindowAttributes(self._hwnd, 0, GREEN_ALPHA, 0x2)  # LWA_ALPHA\n            user32.ShowWindow(self._hwnd, 8)                    # SW_SHOWNA (no activate)\n            # db8 addendum 8 fix: without a message pump on this thread, WM_PAINT never\n            # arrives and the window stays blank. UpdateWindow forces a SYNCHRONOUS paint\n            # (the default window procedure erases the background with the green class\n            # brush), which is all a static tint ever needs.\n            user32.UpdateWindow(self._hwnd)\n            return True\n        except Exception:                                           # noqa: BLE001\n            return False\n\n    def hide(self) -> None:\n        if not self._hwnd:\n            return\n        import ctypes\n        try:\n            ctypes.windll.user32.DestroyWindow(ctypes.c_void_p(self._hwnd))\n        except Exception:                                           # noqa: BLE001\n            pass\n        self._hwnd = 0\n\n\ndef _plain_key_name(vk: int) -> str:\n    \"\"\"The unmodified name of a letter or digit key (virtual codes 0x30-0x39, 0x41-0x5A align\n    with ASCII), so a combination like Ctrl+S records as ctrl+s and not a raw code.\"\"\"\n    if 0x30 <= vk <= 0x39 or 0x41 <= vk <= 0x5A:\n        return chr(vk).lower()\n    return \"\"\n\n\ndef recording_name(when: float | None = None) -> str:\n    \"\"\"The name a finished recording carries on the dashboard's map.\"\"\"\n    return \"record \" + time.strftime(\"%Y-%m-%d %H%M\", time.localtime(when or time.time()))\n\n\ndef should_skip_window(title: str, cls: str, pid: int, own_pid: int | None = None) -> bool:\n    \"\"\"True when a window is not a recording target: ours (the dashboard, the studio, the\n    overlay - anything owned by this process) or a window with no title to bind identity to.\"\"\"\n    if pid and pid == (own_pid or os.getpid()):\n        return True\n    text = (title or \"\").strip()\n    if not text:\n        return True\n    return text.endswith(OWN_TITLE_SUFFIX) or text in OWN_WINDOW_TITLES\n\n\n# --- the assembler: resolved events become the turns of a run ------------------------------\n\ndef _action_timestamp() -> str:\n    return datetime.now().isoformat(timespec=\"microseconds\")\n\n\nclass Assembler:\n    \"\"\"Captured events -> turn documents, through the same `trajectory.Recorder` an agent run\n    uses. Pure logic (no Win32): the tests drive it with synthetic events.\"\"\"\n\n    def __init__(self, recorder: Any, now: Any = None) -> None:\n        self.rec = recorder\n        self._now = now or _action_timestamp\n        self._refs = 0\n        self._text = \"\"\n        self._text_at = \"\"                    # db8 addendum 2: when the FIRST character was typed\n        self._text_win: dict[str, Any] | None = None\n        self._mods: set[str] = set()\n        self._mods_used = False               # db8 addendum 7: was a non-modifier pressed while held?\n        self._path: list[list[int]] = []      # db8 addendum 1: the pointer's trail, kept for the next click\n\n    # -- internals ---------------------------------------------------------------------------\n\n    def _window_identity(self, win: dict[str, Any]) -> dict[str, Any]:\n        identity = {\"handle\": f\"#{win['handle']}\", \"window_title\": win.get(\"title\") or \"\",\n                    \"process\": win.get(\"process\") or \"\"}\n        if win.get(\"pid\") is not None:\n            identity[\"pid\"] = int(win[\"pid\"])\n        return identity\n\n    def _record(self, tool: str, arguments: dict[str, Any], target: dict[str, Any] | None = None,\n                extra: dict[str, Any] | None = None, visible: bool = False) -> None:\n        # outcome \"ok\", effect \"none\": a recorded step executed nothing, so no effect is claimed\n        # (cua-fx1 effect honesty); replay never filters on the outcome, only on read_only/skip.\n        # addendum 5 (the owner: \"the Cursor didn't move to do like as i did\"): every input step\n        # a HUMAN recorded replays in the foreground, real cursor and real keys, exactly what he\n        # watched himself do - the quiet background route stays the agent steps' default.\n        if visible:\n            arguments = {**arguments, \"delivery_mode\": \"foreground\"}\n        timed = dict(extra or {})\n        if \"timestamp\" not in timed:\n            timed[\"timestamp\"] = self._now()\n        self.rec.record(tool=tool, arguments=arguments, outcome=\"ok\", effect=\"none\",\n                        client=dict(CLIENT), target=target, extra=timed)\n\n    def _flush_text(self) -> None:\n        if self._text and self._text_win is not None:\n            win = self._text_win\n            # addendum 2: the turn's timestamp is when the FIRST character was typed, not the\n            # flush (the next click or Enter can end the typing much later)\n            self._record(\"desktop.type\", {\"text\": self._text, \"window\": f\"#{win['handle']}\"},\n                         {\"window\": self._window_identity(win)},\n                         extra={\"timestamp\": self._text_at} if self._text_at else None, visible=True)\n        self._text, self._text_win, self._text_at = \"\", None, \"\"\n\n    # -- the events --------------------------------------------------------------------------\n\n    def key(self, vk: int, *, down: bool, char: str | None = None,\n            win: dict[str, Any] | None = None, injected: bool = False) -> None:\n        \"\"\"One keyboard event. `char` is the character it types (None for non-printing keys);\n        `win` is the identity of the window that had the focus.\"\"\"\n        if injected:\n            return\n        if vk in MODIFIER_KEYS:\n            name = MODIFIER_KEYS[vk]\n            if down:\n                self._mods.add(name)\n                self._mods_used = False\n            else:\n                self._mods.discard(name)\n                # db8 addendum 7 (the owner's live play failed at step 4): a modifier pressed\n                # and released ALONE is an action - the Windows key alone opens Search, and\n                # no other key follows it. Without this step the recording starts at \"type\n                # into the Search box\" and replay stops: the window was never opened.\n                if not self._mods and not self._mods_used:\n                    # addendum 8: NO window guard — the Win key opens the Start menu when\n                    # the desktop has no titled window; recording it is the whole point\n                    arguments: dict[str, Any] = {\"keys\": name}\n                    target = None\n                    if win is not None:\n                        arguments[\"window\"] = f\"#{win['handle']}\"\n                        target = {\"window\": self._window_identity(win)}\n                    extra: dict[str, Any] = {}\n                    if name == \"win\":\n                        extra[\"wait_after_ms\"] = 500     # the Start menu needs a beat to open\n                    self._record(\"desktop.key\", arguments, target,\n                                 extra=extra or None, visible=True)\n                self._mods_used = False\n            return\n        if not down:\n            return\n        if self._mods:\n            self._mods_used = True\n        if win is not None and self._text_win is not None and win[\"handle\"] != self._text_win[\"handle\"]:\n            self._flush_text()                                  # the focus moved: the text belongs to that window\n        if self._mods:\n            # a combination: one desktop.key turn naming the window it went to\n            mods = sorted(self._mods, key=lambda m: MODIFIER_ORDER.get(m, 9))\n            name = (KEY_NAMES.get(vk) or (char or \"\").lower()\n                    or _plain_key_name(vk) or f\"vk{vk:#x}\")\n            arguments: dict[str, Any] = {\"keys\": \"+\".join([*mods, name])}\n            target = None\n            if win is not None:\n                arguments[\"window\"] = f\"#{win['handle']}\"\n                target = {\"window\": self._window_identity(win)}\n            self._record(\"desktop.key\", arguments, target, visible=True)\n            return\n        if vk == 0x08:                                          # Backspace edits what was typed\n            self._text = self._text[:-1]\n            if self._text_win is None and win is not None:\n                self._text_win, self._text_at = win, self._now()\n            return\n        if vk == 0x0D:                                          # Enter: in a console it runs the command\n            self._text += \"\\n\"\n            if self._text_win is None and win is not None:\n                self._text_win = win\n            if win is not None and str(win.get(\"process\") or \"\").lower() in TERMINAL_PROCESSES:\n                self._flush_text()                              # one desktop.type turn per command\n            return\n        if char:\n            self._text += char\n            if self._text_win is None and win is not None:\n                self._text_win, self._text_at = win, self._now()\n            return\n        if vk in KEY_NAMES:                                     # a special key on its own\n            if vk not in (0x08, 0x09, 0x0D, 0x1B, 0x20):         # addendum 5: a NAVIGATION key\n                self._flush_text()                              # ends the text, keeping the true order\n            arguments = {\"keys\": KEY_NAMES[vk]}\n            target = None\n            if win is not None:\n                arguments[\"window\"] = f\"#{win['handle']}\"\n                target = {\"window\": self._window_identity(win)}\n            self._record(\"desktop.key\", arguments, target, visible=True)\n\n    def click(self, x: int, y: int, win: dict[str, Any] | None, element: dict[str, Any] | None,\n              *, button: str = \"left\", double: bool = False, injected: bool = False,\n              at: str | None = None) -> None:\n        \"\"\"One mouse press at (x, y): a ref click when an element was resolved under it, else a\n        coordinate click. Clicks with no window (or on ours) are not recorded at all. The turn\n        carries the pointer's `path` - where it travelled since the previous event (addendum 1) -\n        and `at` stamps the press's own moment (addendum 3: clicks commit on release).\"\"\"\n        if injected or win is None:\n            return\n        self._flush_text()                                      # the click ends what was being typed\n        flags: dict[str, Any] = {}\n        if button == \"right\":\n            flags[\"right\"] = True\n        if double:\n            flags[\"double\"] = True\n        path = list(self._path)\n        self._path = []                                         # the trail belongs to this click alone\n        extra: dict[str, Any] = {\"screen_x\": int(x), \"screen_y\": int(y)}\n        if path:\n            extra[\"path\"] = path\n        if at:\n            extra[\"timestamp\"] = at\n        if element and element.get(\"name\"):\n            self._refs += 1\n            ref = f\"@e{self._refs}\"\n            identity = {\"ref\": ref, \"role\": str(element.get(\"role\") or \"\"),\n                        \"name\": str(element.get(\"name\") or \"\"),\n                        \"window_title\": win.get(\"title\") or \"\", \"process\": win.get(\"process\") or \"\"}\n            for key in (\"automation_id\", \"class_name\"):     # addendum 6: fallback attributes\n                if element.get(key):\n                    identity[key] = str(element[key])\n            self._record(\"desktop.click\", {\"ref\": ref, **flags}, {\"ref\": identity},\n                         extra=extra or None, visible=True)\n        else:\n            self._record(\"desktop.click_at\",\n                         {\"x\": int(x), \"y\": int(y), \"window\": f\"#{win['handle']}\", **flags},\n                         {\"window\": self._window_identity(win)}, extra=extra or None, visible=True)\n\n    def drag(self, from_xy: tuple[int, int], to_xy: tuple[int, int], win: dict[str, Any] | None,\n             *, at: str | None = None) -> None:\n        \"\"\"db8 addendum 3: press-move-release beyond the threshold, ONE desktop.drag turn. The\n        coordinates are the window's own (replay re-finds the window by title and drags within\n        it); without a window rect they stay screen-absolute and the turn carries no window.\"\"\"\n        if win is None:\n            return\n        self._flush_text()\n        rect = _window_rect(int(win[\"handle\"]))\n        extra: dict[str, Any] = {}\n        if at:\n            extra[\"timestamp\"] = at\n        if rect:\n            left, top = rect[0], rect[1]\n            arguments: dict[str, Any] = {\"window\": f\"#{win['handle']}\",\n                                         \"from_x\": from_xy[0] - left, \"from_y\": from_xy[1] - top,\n                                         \"to_x\": to_xy[0] - left, \"to_y\": to_xy[1] - top}\n            target: dict[str, Any] | None = {\"window\": self._window_identity(win)}\n        else:\n            arguments = {\"from_x\": from_xy[0], \"from_y\": from_xy[1],\n                         \"to_x\": to_xy[0], \"to_y\": to_xy[1]}\n            target = None\n        self._record(\"desktop.drag\", arguments, target, extra=extra or None, visible=True)\n\n    def scroll(self, direction: str, amount: int, win: dict[str, Any] | None) -> None:\n        \"\"\"db8 addendum 3: one wheel gesture, a desktop.scroll turn on the window under it.\"\"\"\n        if win is None:\n            return\n        self._record(\"desktop.scroll\", {\"direction\": direction, \"amount\": max(1, int(amount)),\n                                        \"window\": f\"#{win['handle']}\"},\n                     {\"window\": self._window_identity(win)}, visible=True)\n\n    def move(self, x: int, y: int) -> None:\n        \"\"\"The pointer travelled to (x, y): kept (bounded, no repeats) as the trail of the next\n        click. A trail that no click follows is dropped at stop (recorded in the addendum).\"\"\"\n        x, y = int(x), int(y)\n        if self._path and self._path[-1] == [x, y]:\n            return\n        self._path.append([x, y])\n        if len(self._path) > 200:\n            self._path = self._path[-200:]\n\n    def app(self, exe: str, title: str) -> None:\n        \"\"\"A new application the owner launched, as the open_app step replay waits for.\"\"\"\n        if exe.lower() == \"cua-driver.exe\" or title.startswith(\"Cua.AgentCursorOverlay\"):\n            return\n        arguments: dict[str, Any] = {\"command\": exe}\n        if title:\n            arguments[\"wait_title\"] = title[:80]\n        self._record(\"desktop.open_app\", arguments, extra={\"timestamp\": self._now()})\n\n    def flush(self) -> None:\n        self._flush_text()\n\n\n# --- the low-level hooks (Windows, read-only observation) ----------------------------------\n\nWH_KEYBOARD_LL, WH_MOUSE_LL = 13, 14\nWM_QUIT = 0x0012\nWM_MOUSEMOVE, WM_LBUTTONDOWN, WM_RBUTTONDOWN = 0x0200, 0x0201, 0x0204\nWM_LBUTTONUP, WM_RBUTTONUP, WM_MOUSEWHEEL = 0x0202, 0x0205, 0x020A\nWM_LBUTTONDBLCLK = 0x0203            # the SECOND press of a double-click\nDRAG_THRESHOLD_PX = 8                # addendum 3: press-release within this stays a click\nWM_KEYDOWN, WM_KEYUP, WM_SYSKEYDOWN, WM_SYSKEYUP = 0x0100, 0x0101, 0x0104, 0x0105\nLLKHF_INJECTED = 0x10\n\n\ndef _double_click_contract() -> tuple[int, int, int]:\n    if os.name != \"nt\":\n        return 500, 8, 8\n    import ctypes\n    user32 = ctypes.windll.user32\n    return (int(user32.GetDoubleClickTime()), int(user32.GetSystemMetrics(36)),\n            int(user32.GetSystemMetrics(37)))\n\n\ndef _structures():\n    import ctypes\n    from ctypes import wintypes as wt\n\n    class MSLLHOOKSTRUCT(ctypes.Structure):\n        _fields_ = [(\"pt\", wt.POINT), (\"mouseData\", wt.DWORD), (\"flags\", wt.DWORD),\n                    (\"time\", wt.DWORD), (\"dwExtraInfo\", ctypes.c_void_p)]\n\n    class KBDLLHOOKSTRUCT(ctypes.Structure):\n        _fields_ = [(\"vkCode\", wt.DWORD), (\"scanCode\", wt.DWORD), (\"flags\", wt.DWORD),\n                    (\"time\", wt.DWORD), (\"dwExtraInfo\", ctypes.c_void_p)]\n\n    mouse_proc = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, ctypes.c_int, wt.WPARAM,\n                                    ctypes.POINTER(MSLLHOOKSTRUCT))\n    kbd_proc = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, ctypes.c_int, wt.WPARAM,\n                                  ctypes.POINTER(KBDLLHOOKSTRUCT))\n    return MSLLHOOKSTRUCT, KBDLLHOOKSTRUCT, mouse_proc, kbd_proc\n\n\nclass Hooks:\n    \"\"\"WH_MOUSE_LL + WH_KEYBOARD_LL on a daemon thread with a message pump. The callbacks only\n    enqueue what happened and always call the next hook: nothing is intercepted or modified.\n    The green recording overlay is created ON THIS THREAD (addendum 8 fix): its message pump\n    dispatches the overlay's WM_PAINT, which the daemon's RPC thread could never do.\"\"\"\n\n    def __init__(self, out: \"queue.Queue[dict[str, Any]]\",\n                 overlay: \"RecordingOverlay | None\" = None) -> None:\n        self.out = out\n        self.overlay = overlay\n        self.error: str | None = None\n        self._thread: threading.Thread | None = None\n        self._tid = 0\n\n    def start(self) -> None:\n        self._started = threading.Event()\n        self._thread = threading.Thread(target=self._run, daemon=True, name=\"kgrow-record-hooks\")\n        self._thread.start()\n        if not self._started.wait(5):                            # noqa: BLE001 - reported, not raised\n            raise RuntimeError(\"the input hook thread did not start\")\n        if self.error:\n            raise RuntimeError(f\"the input hooks did not install ({self.error})\")\n\n    def alive(self) -> bool:\n        return self._thread is not None and self._thread.is_alive()\n\n    def stop(self, timeout: float = 3.0) -> None:\n        import ctypes\n        if self._tid:\n            ctypes.windll.user32.PostThreadMessageW(self._tid, WM_QUIT, 0, 0)\n        if self._thread is not None:\n            self._thread.join(timeout=timeout)\n            self._thread = None\n\n    def _run(self) -> None:                                     # pragma: no cover - the real pump\n        import ctypes\n        from ctypes import wintypes as wt\n        _, _, mouse_proc, kbd_proc = _structures()\n        user32 = ctypes.WinDLL(\"user32\", use_last_error=True)\n        user32.SetWindowsHookExW.restype = ctypes.c_void_p\n        call_next = user32.CallNextHookEx\n        call_next.restype = ctypes.c_ssize_t\n        out = self.out\n\n        def mouse(nCode, wParam, lParam):\n            try:\n                if nCode >= 0 and wParam in (WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_RBUTTONDOWN,\n                                             WM_LBUTTONUP, WM_RBUTTONUP, WM_MOUSEWHEEL,\n                                             WM_LBUTTONDBLCLK):\n                    m = lParam.contents\n                    now = time.monotonic()\n                    if wParam == WM_MOUSEMOVE:\n                        # addendum 1: the pointer's trail, sampled while it travels (>= 80 ms apart)\n                        if now - last_move[0] < 0.08:\n                            return call_next(None, nCode, wParam, lParam)\n                        last_move[0] = now\n                    cx, cy = _cursor_now()       # THIS process's DPI space, at the event's own moment\n                    kind = (\"move\" if wParam == WM_MOUSEMOVE else\n                            \"wheel\" if wParam == WM_MOUSEWHEEL else \"mouse\")\n                    # addendum 3: the wheel's signed notch count (the delta, in the high word)\n                    delta = ((int(m.mouseData) >> 16) & 0xFFFF)\n                    if delta >= 0x8000:\n                        delta -= 0x10000\n                    out.put({\"t\": kind,\n                             \"x\": m.pt.x, \"y\": m.pt.y, \"cx\": cx, \"cy\": cy,\n                             \"button\": \"right\" if wParam in (WM_RBUTTONDOWN, WM_RBUTTONUP) else \"left\",\n                             \"up\": wParam in (WM_LBUTTONUP, WM_RBUTTONUP),\n                             \"double\": wParam == WM_LBUTTONDBLCLK,\n                             \"delta\": delta,\n                             \"injected\": bool(m.flags & LLKHF_INJECTED)})\n            except Exception:                                   # noqa: BLE001 - observation only\n                pass\n            return call_next(None, nCode, wParam, lParam)\n\n        last_move = [0.0]\n\n        def keyboard(nCode, wParam, lParam):\n            try:\n                if nCode >= 0 and wParam in (WM_KEYDOWN, WM_KEYUP, WM_SYSKEYDOWN, WM_SYSKEYUP):\n                    k = lParam.contents\n                    hwnd = _foreground()                       # the window AT the key's own moment\n                    out.put({\"t\": \"key\", \"vk\": k.vkCode, \"scan\": k.scanCode,\n                             \"down\": wParam in (WM_KEYDOWN, WM_SYSKEYDOWN),\n                             \"hwnd\": hwnd, \"hkl\": _layout_of(hwnd),   # ... and its own keyboard layout\n                             \"injected\": bool(k.flags & LLKHF_INJECTED)})\n            except Exception:                                   # noqa: BLE001 - observation only\n                pass\n            return call_next(None, nCode, wParam, lParam)\n\n        mouse_cb, kbd_cb = mouse_proc(mouse), kbd_proc(keyboard)\n        mouse_hook = user32.SetWindowsHookExW(WH_MOUSE_LL, mouse_cb, None, 0)\n        kbd_hook = user32.SetWindowsHookExW(WH_KEYBOARD_LL, kbd_cb, None, 0)\n        if not mouse_hook or not kbd_hook:\n            self.error = f\"mouse={bool(mouse_hook)} keyboard={bool(kbd_hook)}\"\n            self._started.set()\n            return\n        # db8 addendum 6 (the research pass): SetWinEventHook, out of context, is Microsoft's\n        # documented way to learn of windows appearing and vanishing AS IT HAPPENS\n        # (EVENT_OBJECT_SHOW 0x8002 / EVENT_OBJECT_DESTROY 0x8001, WINEVENT_OUTOFCONTEXT,\n        # a WINEVENTPROC and this same message loop) - no polling gap can miss a splash.\n        OBJID_WINDOW, WINEVENT_OUTOFCONTEXT = 0, 0\n        EVENT_MIN, EVENT_MAX = 0x8001, 0x8002                    # DESTROY..SHOW (one range)\n        winevent_proc = ctypes.WINFUNCTYPE(None, ctypes.c_void_p, ctypes.c_uint, wt.HWND,\n                                           ctypes.c_long, ctypes.c_long, wt.DWORD, wt.DWORD)\n\n        def winevent(_hook, event, hwnd, id_object, _id_child, _thread, _time):\n            try:\n                if id_object == OBJID_WINDOW and hwnd:\n                    out.put({\"t\": \"win_show\" if event == 0x8002 else \"win_gone\",\n                             \"hwnd\": int(hwnd)})\n            except Exception:                                   # noqa: BLE001 - observation only\n                pass\n\n        win_cb = winevent_proc(winevent)\n        win_hook = user32.SetWinEventHook(EVENT_MIN, EVENT_MAX, None, win_cb, 0, 0,\n                                          WINEVENT_OUTOFCONTEXT)\n        # addendum 8: the green overlay is created HERE, on this thread — the message pump\n        # below dispatches its WM_PAINT, which no RPC-handler thread could ever do\n        if self.overlay is not None:\n            self.overlay.show()\n        self._tid = ctypes.windll.kernel32.GetCurrentThreadId()\n        self._started.set()\n        msg = wt.MSG()\n        while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:\n            pass                                                # WM_QUIT ends the pump\n        if self.overlay is not None:\n            self.overlay.hide()\n        user32.UnhookWindowsHookEx(ctypes.c_void_p(mouse_hook))\n        user32.UnhookWindowsHookEx(ctypes.c_void_p(kbd_hook))\n        if win_hook:\n            user32.UnhookWinEvent(ctypes.c_void_p(win_hook))\n\n\n# --- window facts (plain Win32, no COM) -----------------------------------------------------\n\ndef _window_title(hwnd: int) -> str:\n    import ctypes\n    buf = ctypes.create_unicode_buffer(512)\n    ctypes.windll.user32.GetWindowTextW(hwnd, buf, 512)\n    return buf.value or \"\"\n\n\ndef _window_pid(hwnd: int) -> int:\n    import ctypes\n    from ctypes import wintypes as wt\n    pid = wt.DWORD(0)\n    ctypes.windll.user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))\n    return int(pid.value or 0)\n\n\n_PROCESS_NAMES: dict[int, str] = {}\n\n\ndef _process_name(pid: int) -> str:\n    if not pid:\n        return \"\"\n    name = _PROCESS_NAMES.get(pid)\n    if name:\n        return name\n    try:\n        import psutil\n        name = psutil.Process(pid).name()\n    except Exception:                                           # noqa: BLE001 - gone or unreadable\n        name = \"\"\n    _PROCESS_NAMES[pid] = name\n    return name\n\n\ndef _window_at(x: int, y: int) -> int:\n    import ctypes\n    from ctypes import wintypes as wt\n    pt = wt.POINT(x, y)\n    return int(ctypes.windll.user32.WindowFromPoint(pt) or 0)\n\n\ndef _root_window(hwnd: int) -> int:\n    \"\"\"The TOP-LEVEL window of anything under a point. db8 addendum 1: WindowFromPoint returns\n    the child window (Edge's \"Chrome Legacy Window\", Excel's \"Book1\" child) - the skip check,\n    the identity and replay's window matching must all see the root window's title.\"\"\"\n    import ctypes\n    if not hwnd:\n        return 0\n    root = ctypes.windll.user32.GetAncestor(hwnd, 2)              # GA_ROOT\n    return int(root or hwnd)\n\n\ndef _cursor_now() -> tuple[int, int]:\n    \"\"\"The cursor in THIS process's coordinate space (DPI-unaware like the rest of the tool) -\n    at a click it is exactly the click point, and it is the space UIA resolves in.\"\"\"\n    import ctypes\n    from ctypes import wintypes as wt\n    pt = wt.POINT(0, 0)\n    ctypes.windll.user32.GetCursorPos(ctypes.byref(pt))\n    return int(pt.x), int(pt.y)\n\n\ndef _window_rect(hwnd: int) -> tuple[int, int, int, int] | None:\n    \"\"\"(left, top, right, bottom) of a window, or None when it cannot be read.\"\"\"\n    import ctypes\n    from ctypes import wintypes as wt\n    r = wt.RECT(0, 0, 0, 0)\n    if not hwnd or not ctypes.windll.user32.GetWindowRect(hwnd, ctypes.byref(r)):\n        return None\n    return (int(r.left), int(r.top), int(r.right), int(r.bottom))\n\n\ndef _foreground() -> int:\n    import ctypes\n    return int(ctypes.windll.user32.GetForegroundWindow() or 0)\n\n\ndef _layout_of(hwnd: int) -> int:\n    \"\"\"db8 addendum 2: the KEYBOARD LAYOUT of one window's thread. ToUnicodeEx must answer with\n    the focused window's own layout - the owner types the keys of \"excel\" under an Arabic system\n    layout and an English-layout window must still record \"excel\", not its Arabic letters.\"\"\"\n    import ctypes\n    if not hwnd:\n        return 0\n    user32 = ctypes.windll.user32\n    thread = user32.GetWindowThreadProcessId(hwnd, None)\n    return int(user32.GetKeyboardLayout(thread) or 0)\n\n\ndef _top_windows() -> list[tuple[int, int, str]]:\n    \"\"\"Every visible top-level window with a title: (handle, pid, title).\"\"\"\n    import ctypes\n\n    found: list[tuple[int, int, str]] = []\n    seen: set[int] = set()\n\n    @ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_ssize_t)\n    def each(hwnd, _lparam):\n        handle = int(hwnd or 0)\n        if handle and handle not in seen and ctypes.windll.user32.IsWindowVisible(handle):\n            seen.add(handle)\n            found.append((handle, _window_pid(handle), _window_title(handle)))\n        return True\n\n    ctypes.windll.user32.EnumWindows(each, 0)\n    return found\n\n\ndef _element_at(x: int, y: int) -> dict[str, Any] | None:\n    \"\"\"The element under a point as replay identity: the same role string a fresh observe\n    prints, and its name; addendum 6 also carries AutomationId and ClassName (Microsoft:\n    AutomationId is stable across instances and unique among siblings - inert for replay,\n    extra material for the studio's element editor, Selenium IDE's fallback-array spirit).\n    On the executor's COM thread (uia_call); None when nothing usable.\"\"\"\n    from .desktop.executor import uia_call\n\n    def resolve() -> dict[str, Any] | None:\n        import uiautomation as ui\n        from .desktop import uia as uialib\n        try:\n            control = ui.ControlFromPoint(x, y)\n        except Exception:                                       # noqa: BLE001 - best effort identity\n            return None\n        if control is None:\n            return None\n        try:\n            name = str(control.Name or \"\")\n        except Exception:                                       # noqa: BLE001\n            name = \"\"\n        if not name:\n            return None                                         # a nameless element cannot be re-found\n        out = {\"role\": uialib.role_of(control), \"name\": name}\n        try:\n            automation_id = str(control.AutomationId or \"\")\n            if automation_id:\n                out[\"automation_id\"] = automation_id\n        except Exception:                                       # noqa: BLE001\n            pass\n        try:\n            class_name = str(control.ClassName or \"\")\n            if class_name:\n                out[\"class_name\"] = class_name\n        except Exception:                                       # noqa: BLE001\n            pass\n        return out\n\n    try:\n        return uia_call(resolve, timeout=1.5)\n    except Exception:                                           # noqa: BLE001 - identity is best effort\n        return None\n\n\n# --- the recorder ----------------------------------------------------------------------------\n\nclass HumanRecorder:\n    \"\"\"Owns one recording at a time, daemon side. The dashboard's Record button starts and stops\n    it through the `_run.record` control frame; the finished recording is published to the\n    dashboard's map exactly like an ended run (runcontrol.publish_recording).\"\"\"\n\n    def __init__(self, daemon: Any) -> None:\n        self.daemon = daemon\n        self._lock = threading.Lock()\n        self._active: dict[str, Any] | None = None\n        self._seen = 0\n\n    # --- the state the dashboard shows ------------------------------------------------------\n\n    def state(self) -> dict[str, Any]:\n        \"\"\"Cheap and never raising: `_run.state` polls this (a NOT_AUDITED frame).\"\"\"\n        with self._lock:\n            if self._active is None:\n                return {\"active\": False, \"started_at\": None, \"events\": self._seen}\n            return {\"active\": True, \"started_at\": self._active[\"started_at\"],\n                    \"events\": self._seen, \"run_id\": self._active[\"run_id\"]}\n\n    def _note(self, action: str, **fields: Any) -> None:\n        try:\n            self.daemon.run_control.note(\"control\", action=action, **fields)\n        except Exception:                                       # noqa: BLE001 - a view never fails the press\n            pass\n\n    # --- start / stop ------------------------------------------------------------------------\n\n    def start(self) -> dict[str, Any]:\n        with self._lock:\n            if self._active is not None:\n                raise ProtocolError(ErrorCode.UNSUPPORTED, \"a recording is already running\",\n                                    hint=\"Press the square (Stop) first; it stops and keeps the recording.\")\n            if os.name != \"nt\":\n                raise ProtocolError(ErrorCode.UNSUPPORTED, \"the recorder needs Windows\",\n                                    hint=\"The low-level input hooks exist on Windows only.\")\n            self._active = {\"started_at\": time.time(),\n                            \"run_id\": time.strftime(\"%Y%m%d-%H%M%S\") + \"-\" + \"\".join(\n                                secrets.choice(\"abcdefghijklmnopqrstuvwxyz\") for _ in range(4))}\n            active = self._active          # one dict: stop() reads the capture handles _begin_capture adds\n        try:\n            self._begin_capture(active)\n        except Exception as exc:                                # noqa: BLE001 - nothing was captured\n            with self._lock:\n                self._active = None\n            raise ProtocolError(ErrorCode.UNSUPPORTED, f\"the recorder could not start ({exc})\",\n                                hint=\"No recording was made; try again.\") from exc\n        self._note(\"record\", state=\"started\", run_id=active[\"run_id\"])\n        return {\"effect_state\": \"committed\", \"recording\": True, \"run_id\": active[\"run_id\"],\n                \"started_at\": active[\"started_at\"]}\n\n    def stop(self) -> dict[str, Any]:\n        with self._lock:\n            if self._active is None:\n                raise ProtocolError(ErrorCode.UNSUPPORTED, \"no recording is running\",\n                                    hint=\"Press the circle first: it starts recording what you do.\")\n            active = self._active\n            self._active = None\n        turns = self._end_capture(active)\n        published = self.daemon.run_control.publish_recording(\n            active[\"run_id\"], recording_name(active[\"started_at\"]), active[\"started_at\"],\n            active[\"recorder\"])\n        self._note(\"record\", state=\"stopped\", run_id=active[\"run_id\"], turns=turns,\n                   on_map=bool(published))\n        return {\"effect_state\": \"committed\", \"recording\": False, \"run_id\": active[\"run_id\"],\n                \"turns\": turns, \"name\": recording_name(active[\"started_at\"]),\n                \"on_map\": bool(published)}\n\n    # --- the capture -------------------------------------------------------------------------\n\n    def _begin_capture(self, active: dict[str, Any]) -> None:\n        from .trajectory import Recorder\n        active[\"recorder\"] = Recorder(self.daemon.home, active[\"run_id\"])\n        active[\"assembler\"] = Assembler(active[\"recorder\"])\n        active[\"events\"] = queue.Queue()\n        active[\"stop\"] = threading.Event()\n        # addendum 8: the owner's green recording indicator — created ON THE HOOKS THREAD\n        # (its message pump dispatches WM_PAINT; the RPC handler thread has no pump, so the\n        # window existed but never painted — the owner's screenshot proved it)\n        overlay = RecordingOverlay()\n        active[\"overlay\"] = overlay\n        active[\"hooks\"] = Hooks(active[\"events\"], overlay=overlay)\n        active[\"hooks\"].start()\n        active[\"baseline\"] = {pid for _hwnd, pid, title in _top_windows()\n                              if not should_skip_window(title, \"\", pid)}\n        active[\"launched\"] = set()\n        active[\"known\"] = {}                                       # addendum 3: handle -> (title, process)\n        active[\"pending\"] = None                                   # addendum 3: the press awaiting release\n        active[\"worker\"] = threading.Thread(target=self._worker, args=(active,), daemon=True,\n                                            name=\"kgrow-record-worker\")\n        active[\"worker\"].start()\n        active[\"poller\"] = threading.Thread(target=self._poll_windows, args=(active,), daemon=True,\n                                            name=\"kgrow-record-poller\")\n        active[\"poller\"].start()\n\n    def _end_capture(self, active: dict[str, Any]) -> int:\n        active[\"stop\"].set()\n        active[\"hooks\"].stop()          # the hooks thread hides the overlay as its pump exits\n        worker = active.get(\"worker\")\n        if worker is not None:\n            worker.join(timeout=10.0)\n        assembler: Assembler = active[\"assembler\"]\n        pending = active.get(\"pending\")                            # a press never released: a click\n        if pending:\n            active[\"pending\"] = None\n            assembler.click(pending[\"x\"], pending[\"y\"], pending[\"win\"], pending[\"element\"],\n                            at=pending[\"at\"], double=bool(pending.get(\"double\")))\n        assembler.flush()\n        return self._order_by_time(active)\n\n    def _order_by_time(self, active: dict[str, Any]) -> int:\n        \"\"\"db8 addendum 5 (the owner's play: the steps ran in the wrong order): turns are\n        written in FLUSH order, and typing flushes late (the next click ends it), so the file\n        order can differ from what the owner did. Rewrite the run's turns in ACTION order\n        (their timestamps, stable within a second) before publishing, so Play does exactly\n        what he did. Every field of each turn is kept as recorded.\"\"\"\n        import shutil\n        from .trajectory import Recorder, _write_json, load_turns, turn_dirs\n        recorder: Recorder = active[\"recorder\"]\n        turns = load_turns(recorder.folder)\n        if len(turns) < 2:\n            return int(recorder.count)\n        ordered = sorted(turns, key=lambda t: str(t.get(\"timestamp\") or \"\"))   # stable sort\n        if [t.get(\"tool\") for t in ordered] == [t.get(\"tool\") for t in turns]:\n            return int(recorder.count)\n        for turn_dir in turn_dirs(recorder.folder):\n            shutil.rmtree(turn_dir, ignore_errors=True)\n        for number, turn in enumerate(ordered, start=1):\n            turn[\"turn\"] = number\n            _write_json(recorder.folder / f\"turn-{number:05d}\" / \"action.json\", turn)  # noqa: SLF001\n        fresh = Recorder(self.daemon.home, recorder.run_id)\n        fresh.count = len(ordered)\n        active[\"recorder\"] = fresh\n        return fresh.count\n\n    def _worker(self, active: dict[str, Any]) -> None:\n        \"\"\"Turns raw hook events into resolved assembler calls. All Win32 reads happen here\n        (plain, no COM); element identity goes through the executor's single COM thread.\"\"\"\n        import ctypes\n        events: \"queue.Queue[dict[str, Any]]\" = active[\"events\"]\n        stop: threading.Event = active[\"stop\"]\n        keystate = (ctypes.c_uint8 * 256)()\n        user32 = ctypes.windll.user32\n        buf = ctypes.create_unicode_buffer(16)\n        to_unicode = user32.ToUnicodeEx\n        to_unicode.restype = ctypes.c_int\n        while True:\n            try:\n                event = events.get(timeout=0.2)\n            except queue.Empty:\n                if stop.is_set():\n                    return\n                continue\n            try:\n                self._seen += 1\n                if event[\"t\"] == \"move\":\n                    self._on_move(active, event)\n                elif event[\"t\"] == \"wheel\":\n                    self._on_wheel(active, event)\n                elif event[\"t\"] in (\"win_show\", \"win_gone\"):\n                    self._on_win_event(active, event)\n                elif event[\"t\"] == \"mouse\":\n                    self._on_mouse(active, event)\n                else:\n                    self._on_key(active, event, keystate, to_unicode, buf)\n            except Exception:                                   # noqa: BLE001 - one event never ends it\n                continue\n\n    def _on_move(self, active: dict[str, Any], event: dict[str, Any]) -> None:\n        if event.get(\"injected\"):\n            return\n        cx, cy = event.get(\"cx\"), event.get(\"cy\")\n        if cx is None or cy is None:\n            return\n        active[\"assembler\"].move(cx, cy)\n\n    def _on_win_event(self, active: dict[str, Any], event: dict[str, Any]) -> None:\n        \"\"\"db8 addendum 6: a window appeared or vanished THIS INSTANT (SetWinEventHook,\n        EVENT_OBJECT_SHOW/DESTROY) - the poller's 1.5 s gap cannot miss it. db8 addendum 7:\n        only ROOT windows are tracked - the event fires for every CHILD panel too (Excel's\n        Ribbon, Status Bar, DropShadowTop; the Search flyout's CoreInput), and those closes\n        are replay noise (the owner's 44-step recording carried 11 of them).\"\"\"\n        hwnd = int(event.get(\"hwnd\") or 0)\n        if not hwnd or _root_window(hwnd) != hwnd:   # a child panel: not a window replay names\n            return\n        known: dict[int, Any] = active.setdefault(\"known\", {})\n        if event[\"t\"] == \"win_show\":\n            pid = _window_pid(hwnd)\n            if pid and pid not in active[\"baseline\"] and pid != os.getpid() \\\n                    and not should_skip_window(_window_title(hwnd), \"\", pid):\n                title = _window_title(hwnd)\n                if title and hwnd not in known:\n                    known[hwnd] = (title, _process_name(pid), time.monotonic())\n            return\n        entry = known.pop(hwnd, None)\n        if entry is None:\n            return\n        identity, born = (entry[0], entry[1]), entry[2]\n        # addendum 8: a window that lived < 2 seconds is a tooltip or a cell-reference\n        # popup (the owner's 36-step recording carried 26 of them) — not a replay step\n        if time.monotonic() - born < 2.0:\n            return\n        active[\"assembler\"]._record(                      # noqa: SLF001 - same module\n            \"desktop.close_window\", {\"window\": f\"#{hwnd}\"},\n            {\"window\": {\"handle\": f\"#{hwnd}\", \"window_title\": identity[0],\n                        \"process\": identity[1] or \"\"}},\n            extra={\"optional\": True})\n\n    def _window_under(self, x: int, y: int) -> dict[str, Any] | None:\n        \"\"\"The root window under a point as an identity dict; None for ours or nothing.\"\"\"\n        hwnd = _root_window(_window_at(int(x), int(y)))            # the root window, not a child\n        if not hwnd:\n            return None\n        pid = _window_pid(hwnd)\n        title = _window_title(hwnd)\n        if should_skip_window(title, \"\", pid):\n            return None\n        return {\"handle\": hwnd, \"title\": title, \"process\": _process_name(pid), \"pid\": pid}\n\n    def _on_wheel(self, active: dict[str, Any], event: dict[str, Any]) -> None:\n        \"\"\"db8 addendum 3: one wheel gesture = one desktop.scroll turn on the window under it.\"\"\"\n        if event.get(\"injected\"):\n            return\n        x, y = event.get(\"cx\"), event.get(\"cy\")\n        if x is None or y is None:\n            return\n        win = self._window_under(int(x), int(y))\n        if win is None:\n            return\n        delta = int(event.get(\"delta\") or 0)\n        notches = max(1, round(abs(delta) / 120))                  # one notch is 120\n        # db8 addendum 9: Microsoft docs — positive delta = wheel rotated FORWARD (away from\n        # the user) = scroll UP; negative = backward (toward the user) = scroll DOWN.\n        # The old code had the directions inverted (found by the owner's live test).\n        active[\"assembler\"].scroll(\"up\" if delta > 0 else \"down\", notches, win)\n\n    def _on_mouse(self, active: dict[str, Any], event: dict[str, Any]) -> None:\n        if event.get(\"injected\"):\n            return\n        # addendum 1: the point captured WITH the event (this process's DPI space, where UIA\n        # resolves) - never wherever the cursor is by the time the queue reaches the click.\n        x, y = event.get(\"cx\"), event.get(\"cy\")\n        if x is None or y is None:\n            x, y = _cursor_now()\n        x, y = int(x), int(y)\n        now = time.monotonic()\n        button = str(event.get(\"button\") or \"left\")\n        if button != \"left\" or not event.get(\"up\"):\n            if not event.get(\"up\") and button == \"right\":\n                win = self._window_under(x, y)                     # right click: as before, on press\n                if win is not None:\n                    active[\"assembler\"].click(x, y, win, _element_at(x, y), button=\"right\",\n                                              at=self._now_stamp(active))\n                return\n            # addendum 3: a LEFT PRESS holds its identity (element under the press point) and\n            # commits on RELEASE - as a click when the release is close, else as one drag.\n            if not event.get(\"up\"):\n                win = self._window_under(x, y)\n                last = active.get(\"last_click\")\n                double = bool(event.get(\"double\"))\n                if last:\n                    milliseconds, max_dx, max_dy = _double_click_contract()\n                    double = double or ((now - last[\"at\"]) * 1000 <= milliseconds\n                                        and abs(x - last[\"x\"]) <= max_dx\n                                        and abs(y - last[\"y\"]) <= max_dy)\n                active[\"pending\"] = None if win is None else {\n                    \"x\": x, \"y\": y, \"win\": win, \"element\": _element_at(x, y),\n                    \"at\": self._now_stamp(active), \"double\": double}\n            return\n        pending = active.get(\"pending\")\n        active[\"pending\"] = None\n        if not pending:\n            return\n        far = (abs(x - pending[\"x\"]) + abs(y - pending[\"y\"])) > DRAG_THRESHOLD_PX\n        if far:\n            active[\"last_click\"] = None\n            active[\"assembler\"].drag((pending[\"x\"], pending[\"y\"]), (x, y), pending[\"win\"],\n                                     at=pending[\"at\"])\n        else:\n            active[\"assembler\"].click(pending[\"x\"], pending[\"y\"], pending[\"win\"], pending[\"element\"],\n                                      at=pending[\"at\"],\n                                      double=bool(pending.get(\"double\")))\n            active[\"last_click\"] = {\"x\": pending[\"x\"], \"y\": pending[\"y\"], \"at\": now}\n\n    @staticmethod\n    def _now_stamp(_active: dict[str, Any]) -> str:\n        return _action_timestamp()\n\n    def _on_key(self, active: dict[str, Any], event: dict[str, Any], keystate: Any,\n                to_unicode: Any, buf: Any) -> None:\n        vk, down = int(event.get(\"vk\") or 0), bool(event.get(\"down\"))\n        if vk:\n            keystate[vk] = 0x80 if down else 0x00\n        # addendum 1: the foreground window captured with the event by the hook itself\n        hwnd = int(event.get(\"hwnd\") or 0) or _foreground()\n        pid = _window_pid(hwnd)\n        title = _window_title(hwnd)\n        win = None\n        if hwnd and not should_skip_window(title, \"\", pid):\n            win = {\"handle\": hwnd, \"title\": title, \"process\": _process_name(pid)}\n        char: str | None = None\n        if down and vk and vk not in MODIFIER_KEYS and not active[\"assembler\"]._mods:  # noqa: SLF001\n            # no modifiers held: the key types its character (with Ctrl held ToUnicodeEx would\n            # answer a control character; the assembler names combinations from the key itself)\n            hkl = int(event.get(\"hkl\") or 0) or None\n            count = to_unicode(vk, int(event.get(\"scan\") or 0), keystate, buf, 16, 0, hkl)\n            if count > 0:\n                char = str(buf.value[:count])\n        active[\"assembler\"].key(vk, down=down, char=char, win=win,\n                                injected=bool(event.get(\"injected\")))\n\n    def _poll_windows(self, active: dict[str, Any]) -> None:\n        \"\"\"The poller thread: every 1.5 s one pass - launches, vanished windows, the hooks.\"\"\"\n        stop: threading.Event = active[\"stop\"]\n        while not stop.wait(1.5):\n            try:\n                self._poll_once(active)\n            except Exception:                                   # noqa: BLE001 - a view never fails\n                continue\n\n    def _poll_once(self, active: dict[str, Any]) -> None:\n        \"\"\"One poll pass (its own method so the tests drive exactly this): new applications,\n        windows that appeared and then vanished (a close step), and the hooks watchdog.\"\"\"\n        # addendum 3: the prompt's \"auto-restart capture adapters\" - one line of it\n        hooks = active.get(\"hooks\")\n        if hooks is not None and hasattr(hooks, \"alive\") and not hooks.alive():\n            fresh = Hooks(active[\"events\"])\n            fresh.start()\n            active[\"hooks\"] = fresh\n        injected = active.get(\"poller_windows\")\n        if injected is not None:            # the tests inject a queue of snapshots, one per pass\n            windows = injected.pop(0) if injected else []\n        else:\n            windows = _top_windows()\n        known: dict[int, Any] = active.setdefault(\"known\", {})\n        seen: dict[int, Any] = {}\n        for hwnd, pid, title in windows:\n            if pid in active[\"baseline\"] or pid in active[\"launched\"]:\n                # addendum 4: only windows replay can NAME are tracked (an untitled window can\n                # never be found again, so its vanishing is not a step)\n                if pid not in active[\"baseline\"] and not should_skip_window(title, \"\", pid):\n                    seen[hwnd] = known.get(hwnd) or (title, _process_name(pid))\n                continue\n            if should_skip_window(title, \"\", pid):\n                active[\"launched\"].add(pid)\n                continue\n            exe = _process_name(pid)\n            if not exe:\n                continue\n            active[\"launched\"].add(pid)\n            active[\"assembler\"].app(exe, title)\n            seen[hwnd] = (title, exe, time.monotonic())\n        # addendum 3: a window that APPEARED during the recording and has now vanished is a\n        # close step (replay symmetry with its open). Windows from before the recording are not\n        # recorded as closes - their opening was not recorded either (the rule is in the plan).\n        # addendum 4: the step is OPTIONAL - a splash or a transient window that no longer\n        # exists when the workflow runs must never stop the whole replay (found in the owner's\n        # own play: Excel opened, then the replay stopped on the splash's close step).\n        for hwnd, identity in known.items():\n            if hwnd not in seen:\n                assembler: Assembler = active[\"assembler\"]\n                assembler._record(                      # noqa: SLF001 - same module\n                    \"desktop.close_window\", {\"window\": f\"#{hwnd}\"},\n                    {\"window\": {\"handle\": f\"#{hwnd}\", \"window_title\": identity[0],\n                                \"process\": identity[1] or \"\"}},\n                    extra={\"optional\": True})\n        active[\"known\"] = seen\n");
